<template>
  <section class="traffic-owner" data-activity-private>
    <header class="owner-heading"><div><span class="traffic-kicker">Owner workspace</span><h2>Behind each visit</h2></div><button class="traffic-text-button" @click="download">Export this report <ArrowUpRightIcon/></button></header>
    <div class="owner-tabs" role="tablist" aria-label="Private reports"><button v-for="item in ['Journeys','Feedback','Quality','Exclusions']" :key="item" role="tab" :aria-selected="tab===item" @click="selectTab(item)">{{ item }}</button></div>
    <div v-if="tab==='Journeys'" class="owner-panel">
      <div class="owner-filters">
        <TrafficSelect label="Country" :value="filters.country || ''" :options="countryOptions" @select="$emit('filter','country',$event)"/>
        <TrafficSelect label="Device" :value="filters.device || ''" :options="deviceOptions" @select="$emit('filter','device',$event)"/>
        <TrafficSelect label="Experience" :value="filters.presentation || ''" :options="experienceOptions" @select="$emit('filter','presentation',$event)"/>
      </div>
      <p class="traffic-note">Filters apply to the latest 100 matching journeys. Historical Google Analytics visits are included in the charts above as aggregate counts.</p>
      <p v-if="filterError" class="traffic-note" role="alert">{{ filterError }}</p><ol class="owner-sessions" :class="{'is-updating':filterBusy}" :aria-busy="filterBusy"><li v-for="session in report.sessions" :key="session.session_id">
        <button class="owner-session" :aria-expanded="selected===session.session_id" @click="openSession(session)"><span class="session-dot"/><span><strong>{{ countryName(session.country) }}</strong><small>{{ session.device }} · {{ date(session.started_at) }}</small></span><span class="session-id">{{ session.visitor_id.slice(0,8) }}</span><span>{{ duration(session.visible_ms) }}<small>{{ session.stops }} stops</small></span><svg viewBox="0 0 16 16" aria-hidden="true" :class="{turned:selected===session.session_id}"><path d="m5 3 5 5-5 5"/></svg></button>
        <div v-if="selected===session.session_id" class="owner-journey"><div class="journey-meta"><span>{{ session.referrer || 'Direct visit' }}</span><button class="traffic-text-button" @click="exclude(session.visitor_id)">Exclude this browser</button></div><p v-if="busy" role="status">Loading journey…</p><p v-if="error" role="alert">{{ error }}</p>
          <ol><li v-for="visit in visits" :key="visit.id"><button class="journey-stop" :aria-expanded="!!actions[visit.id]" @click="openVisit(visit)"><time>{{ time(visit.started_at) }}</time><span><strong>{{ visit.title || visit.path }}</strong><small>{{ visit.presentation }} · {{ visit.place || 'Page opened' }}</small></span><span>{{ duration(visit.visible_ms) }}</span></button><ol v-if="actions[visit.id]" class="journey-actions"><li v-for="event in actions[visit.id].events" :key="event.id"><time>{{ time(event.occurred_at) }}</time><span>{{ event.action.replaceAll('_',' ') }} <strong>{{ event.target }}</strong><small v-if="event.detail">{{ event.detail }}</small></span></li><li v-if="actions[visit.id].error" role="alert">{{ actions[visit.id].error }}</li><li v-if="!actions[visit.id].events.length">{{ actions[visit.id].busy ? 'Loading interactions…' : 'No interactions recorded here.' }}</li><li v-if="actions[visit.id].next!==null"><button class="traffic-text-button" @click="openVisit(visit,true)">More interactions</button></li></ol></li></ol>
          <button v-if="nextVisit!==null" class="traffic-text-button" @click="loadSession(true)">Earlier stops</button>
        </div>
      </li></ol><div v-if="!report.sessions?.length" class="owner-journey-empty"><strong>{{ filterBusy ? 'Finding journeys…' : Object.keys(filters).length ? 'No individual journeys match these filters yet.' : 'Individual journeys will appear with new visits.' }}</strong><p>Earlier visits remain available in the overview. New visits add the sequence of pages, exhibitions and interactions here.</p><button v-if="Object.keys(filters).length" class="traffic-text-button" @click="$emit('filter','','')">Clear filters</button></div>
    </div>
    <div v-else-if="tab==='Feedback'" class="owner-panel"><div class="feedback-switch"><button v-for="kind in ['Ratings','Guestbook']" :key="kind" :aria-pressed="feedbackKind===kind" @click="feedbackKind=kind;loadFeedback()">{{ kind }}</button></div><p class="traffic-note">Ratings and optional feedback are private. Guestbook notes also appear in their exhibitions.</p><p v-if="busy" role="status">Loading responses…</p><p v-if="error" role="alert">{{ error }}</p><ul class="owner-responses"><li v-for="row in responses" :key="row.id"><div><router-link :to="`/view/${row.share_id}`">{{ row.title }}</router-link><strong v-if="row.rating" class="response-rating">{{ row.rating }} <small>/ 5</small></strong></div><p v-if="row.text">{{ row.text }}</p><small>{{ date(row.created_at) }} · {{ visitorContextLabel(row.visitor_context_json) }}</small></li></ul><p v-if="!busy&&!responses.length" class="traffic-empty">No responses yet.</p><button v-if="nextResponse!==null" class="traffic-text-button" @click="loadFeedback(true)">More responses</button></div>
    <div v-else-if="tab==='Quality'" class="owner-panel"><h3>How the site feels</h3><p class="traffic-note">Core Web Vitals at the 75th percentile of the latest 3,000 recorded measurements in this period. Low sample counts need more visits before a trend becomes reliable.</p><div class="vitals-grid"><article v-for="vital in report.performance" :key="vital.metric"><span>{{ vital.metric }}</span><strong>{{ vital.p75===null ? '—' : vital.metric==='CLS' ? vital.p75.toFixed(3) : `${(vital.p75/1000).toFixed(2)}s` }}</strong><p>{{ vital.metric==='LCP'?'Main content visible':vital.metric==='INP'?'Response to interaction':'Layout stability' }}</p><small>{{ vital.samples }} measurements</small></article></div><h3>Search and Ask</h3><p class="traffic-note">Measured in production sessions recorded by this dashboard.</p><dl class="health-list"><div><dt>Searches</dt><dd>{{ report.search?.searches || 0 }}</dd></div><div><dt>Searches with a result opened</dt><dd>{{ report.search?.searches_with_clicks || 0 }}</dd></div><div><dt>Searches without results</dt><dd>{{ report.search?.empty_results || 0 }}</dd></div><div><dt>Ask responses</dt><dd>{{ report.ask?.answers || 0 }}</dd></div><div><dt>Average time to first word</dt><dd>{{ report.ask?.first_token_ms != null ? duration(report.ask.first_token_ms) : 'Awaiting responses' }}</dd></div><div><dt>Average complete response</dt><dd>{{ report.ask?.total_ms != null ? duration(report.ask.total_ms) : 'Awaiting responses' }}</dd></div><div><dt>Failed / cancelled answers</dt><dd>{{ report.ask?.errors || 0 }} / {{ report.ask?.cancelled || 0 }}</dd></div></dl><h3>Collection health</h3><dl class="health-list"><div><dt>Last visit received</dt><dd>{{ report.health?.last_received ? date(report.health.last_received) : 'Waiting for a visit' }}</dd></div><div><dt>Test records excluded</dt><dd>{{ report.health?.test_records || 0 }}</dd></div><div><dt>Excluded browsers</dt><dd>{{ report.excluded?.browsers || 0 }}</dd></div><div><dt>GA4 event retention</dt><dd>14 months</dd></div><div><dt>Site activity retention</dt><dd>Retained in the site database</dd></div></dl></div>
    <div v-else class="owner-panel"><h3>A clean view of visitor traffic</h3><p class="traffic-note">Local previews and embedded demonstrations are excluded before collection. Owner and test browsers can be excluded here without deleting their earlier records.</p><label class="owner-exclude"><input v-model="excludeSelf" type="checkbox" @change="toggleSelf"/> Exclude this browser on future visits</label><p v-if="notice" role="status" class="traffic-note">{{ notice }}</p><p v-if="error" role="alert">{{ error }}</p><ul class="exclusion-list"><li v-for="row in exclusions" :key="row.visitor_id"><span>{{ row.visitor_id.slice(0,8) }}<small>{{ date(row.created_at) }}</small></span><button class="traffic-text-button" @click="restore(row.visitor_id)">Include again</button></li></ul></div>
  </section>
</template>
<script setup>
/* global defineProps, defineEmits */
import {ref,computed,onBeforeUnmount,watch} from 'vue';
import TrafficSelect from './TrafficSelect.vue';
import {listVisitorActivity,listVisitorNotes,listExhibitionFeedback,listTrafficExclusions,setTrafficExclusion} from '../../utils/viewShareSite';
import {countryName,visitorContextLabel} from '../../utils/visitorContextLabel';
import {excludeOwnerBrowser,OWNER_EXCLUSION_KEY} from '../../utils/analyticsPolicy';
const props=defineProps({report:{type:Object,required:true},filters:{type:Object,default:()=>({})},filterBusy:Boolean,filterError:{type:String,default:''}}),emit=defineEmits(['refresh','filter']);
const tab=ref('Journeys'),selected=ref(''),visits=ref([]),actions=ref({}),busy=ref(false),error=ref(''),nextVisit=ref(null),feedbackKind=ref('Ratings'),responses=ref([]),nextResponse=ref(null),exclusions=ref([]),notice=ref('');
const countryOptions=computed(()=>[{value:'',label:'All countries'},...props.report.countries.map(row=>({value:row.country,label:countryName(row.country)})).sort((a,b)=>a.label.localeCompare(b.label))]);
const deviceOptions=[{value:'',label:'All devices'},{value:'desktop',label:'Desktop'},{value:'phone',label:'Phone'},{value:'tablet',label:'Tablet'}];
const experienceOptions=[{value:'',label:'All experiences'},{value:'page',label:'Website pages'},{value:'article',label:'Articles'},{value:'gallery',label:'Gallery'},{value:'exhibition',label:'Exhibitions'}];
watch(()=>props.filters,()=>{selected.value='';visits.value=[];actions.value={};request++;});
const excludeSelf=ref(localStorage.getItem(OWNER_EXCLUSION_KEY)==='1');
let request=0,disposed=false;
onBeforeUnmount(()=>{disposed=true;request++;});
const duration=ms=>{const s=Math.round((ms||0)/1000);return s<60?`${s}s`:s<3600?`${Math.floor(s/60)}m ${s%60}s`:`${Math.floor(s/3600)}h ${Math.floor(s%3600/60)}m`;};
const date=value=>new Date(value).toLocaleString('en',{dateStyle:'medium',timeStyle:'short'});
const time=value=>new Date(value).toLocaleTimeString('en',{hour:'2-digit',minute:'2-digit',hour12:false});
function selectTab(value){tab.value=value;request++;busy.value=false;error.value='';if(value==='Feedback')loadFeedback();if(value==='Exclusions')loadExclusions();}
function openSession(session){selected.value=selected.value===session.session_id?'':session.session_id;visits.value=[];actions.value={};nextVisit.value=null;request++;if(selected.value)loadSession();}
async function loadSession(more=false){const id=selected.value,token=++request;busy.value=true;error.value='';try{const result=await listVisitorActivity({session:id,...(more?{before:nextVisit.value}:{})});if(disposed||token!==request)return;visits.value=[...(more?visits.value:[]),...result.visits].sort((a,b)=>a.started_at-b.started_at);nextVisit.value=result.next;}catch{if(token===request)error.value='This journey could not be loaded. Open it again to retry.';}finally{if(token===request)busy.value=false;}}
async function openVisit(visit,more=false){if(actions.value[visit.id]&&!more){delete actions.value[visit.id];return;}const row=more?actions.value[visit.id]:{events:[],next:null,busy:true,error:''};actions.value[visit.id]=row;const reactive=actions.value[visit.id];reactive.busy=true;try{const result=await listVisitorActivity({visit:visit.id,offset:more?row.next:0});reactive.events.push(...result.events);reactive.next=result.next;}catch{reactive.error='Interactions could not be loaded. Reopen this stop to retry.';}finally{reactive.busy=false;}}
async function loadFeedback(more=false){const token=++request;busy.value=true;error.value='';if(!more)responses.value=[];try{const result=await(feedbackKind.value==='Ratings'?listExhibitionFeedback:listVisitorNotes)(more?nextResponse.value:0);if(disposed||token!==request)return;responses.value=[...(more?responses.value:[]),...(result.feedback||result.notes||[])];nextResponse.value=result.next_offset;}catch{if(token===request)error.value='Responses are temporarily unavailable. Select the tab again to retry.';}finally{if(token===request)busy.value=false;}}
async function loadExclusions(){try{const result=await listTrafficExclusions();if(!disposed)exclusions.value=result.exclusions||[];}catch{error.value='Exclusions could not be loaded.';}}
async function exclude(id){try{await setTrafficExclusion(id);selected.value='';emit('refresh');notice.value='Browser excluded. You can include it again here.';selectTab('Exclusions');}catch{error.value='This browser could not be excluded. Please try again.';}}
async function restore(id){try{await setTrafficExclusion(id,false);await loadExclusions();emit('refresh');}catch{error.value='This change could not be saved. Please try again.';}}
async function toggleSelf(){excludeOwnerBrowser(excludeSelf.value);try{const saved=JSON.parse(localStorage.getItem('site_visitor:v1')||'null');if(saved?.id)await setTrafficExclusion(saved.id,excludeSelf.value);notice.value=excludeSelf.value?'Your future visits on this browser are excluded.':'This browser will be included after you sign out.';await loadExclusions();emit('refresh');}catch{error.value='Future visits are excluded locally. Earlier records could not be updated yet.';}}
function download(){const url=URL.createObjectURL(new Blob([JSON.stringify(props.report,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=`traffic-private-${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
</script>
