.owner-sessions{transition:opacity 120ms}.owner-sessions.is-updating{opacity:.45;pointer-events:none}.owner-journey-empty{padding:1.4rem 0;max-width:56ch}.owner-journey-empty strong{font-size:.86rem;font-weight:400}.owner-journey-empty p{font-size:.76rem;line-height:1.6;color:var(--traffic-muted);margin:.6rem 0}
